    if not history:
        return {"value": None, "unresolved": True}

    def simulate(actions, put_mode, instrument, channel_mode):
        # put_mode: 0=IGNORE, 1=REPLACE, 2=UPSERT
        # instrument: 0=none, 1=AFTER INSERT trigger
        # channel_mode: 0=main changes(), 1=main total_changes, 2=main+other total_changes
        items = {}
        log = []
        main_changes = 0
        main_total = 0
        other_total = 0
        in_tx = {"main": False, "other": False}
        tx_items = {"main": None, "other": None}
        tx_log = {"main": None, "other": None}

        def do_put(conn, key, value):
            nonlocal main_changes, main_total, other_total
            cur = items if not in_tx[conn] else tx_items[conn]
            cur_log = log if not in_tx[conn] else tx_log[conn]
            changed = 0
            inserted = False
            if put_mode == 0:
                if key not in cur:
